# -*- coding: utf-8 -*-
# AUTO-GENERATED Phase-5.
GLOSSARY_ADD = [
    {"term": "Germination", "defn": "Germination is a sequence in which a seed in dormancy absorbs water and becomes active. Then the seed extends its first root and its first shoot.", "tags": ["reference"]},
    {"term": "Taproot (radicle)", "defn": "The taproot (radicle) is the first white root that extends from a seed. It becomes longer in the down direction, to hold the plant in position and to find water.", "tags": ["reference"]},
    {"term": "Cotyledons", "defn": "Cotyledons, or seed leaves, are the two rounded leaves of the embryo that you see first. They contain nutrients and supply them to the seedling.", "tags": ["reference"]},
    {"term": "True leaves", "defn": "True leaves are the usual cannabis leaves, with serrations on the edges. They follow the cotyledons. When the true leaves occur, you start to apply feed.", "tags": ["reference"]},
    {"term": "Seed coat", "defn": "The seed coat is the hard outer shell of the seed. It gives protection to the embryo until the conditions are correct for the seed to germinate.", "tags": ["reference"]},
    {"term": "Embryo", "defn": "The embryo is the very small plant in the seed. It contains a root, two cotyledons and a shoot.", "tags": ["reference"]},
    {"term": "Viable / viability", "defn": "Viability is the condition in which a seed has life and can germinate. The viability decreases when you keep the seeds for a long time or in incorrect conditions.", "tags": ["reference"]},
    {"term": "Germination rate", "defn": "The germination rate is the percentage of the seeds in a batch that germinate.", "tags": ["reference"]},
    {"term": "Feminised seed", "defn": "A feminized seed is a seed that a breeder makes to give almost only female plants. Thus it is not necessary to identify and remove male plants.", "tags": ["reference"]},
    {"term": "Regular seed", "defn": "A regular seed is a seed without treatment. It gives approximately equal quantities of male plants and female plants.", "tags": ["reference"]},
    {"term": "Autoflower seed", "defn": "An autoflower seed is a seed with ruderalis genetics. The plant starts flowering automatically after a small number of weeks, and the photoperiod does not change this.", "tags": ["reference"]},
    {"term": "Photoperiod plant", "defn": "A photoperiod plant starts flowering only when the hours of light in each day decrease to approximately 12. Regular seeds and feminized seeds give photoperiod plants.", "tags": ["reference"]},
    {"term": "Cannabis ruderalis", "defn": "Cannabis ruderalis is a strong subspecies of cannabis. Its genetics give autoflowers the automatic flowering that the photoperiod does not control.", "tags": ["reference"]},
    {"term": "Damping-off", "defn": "Damping-off is a fungal disease (Pythium, Fusarium, Rhizoctonia). It causes rot in the seedling at the level of the soil, and it usually kills the seedling.", "tags": ["reference"]},
    {"term": "Humidity dome", "defn": "A humidity dome is a transparent lid that you put above seedlings. It keeps the moisture near the plants and keeps the humidity high while the roots are very small.", "tags": ["reference"]},
    {"term": "Imbibition", "defn": "Imbibition is the first step of germination. In this step, the seed absorbs water and becomes larger.", "tags": ["reference"]},
    {"term": "PAR (Photosynthetically Active Radiation)", "defn": "PAR (photosynthetically active radiation) is the range of wavelengths from 400 to 700 nm that plants can use for photosynthesis. Lumens, lux and watts do not measure PAR. Thus they do not show the performance of a grow light for plants.", "tags": ["reference"]},
    {"term": "PPFD (Photosynthetic Photon Flux Density)", "defn": "PPFD (photosynthetic photon flux density) is the number of photons in the PAR range that one square meter receives in each second. You measure it in micromoles for each square meter for each second (umol/m2/s). It shows how bright the light is at the canopy, and you read it with a quantum meter or PAR meter.", "tags": ["reference"]},
    {"term": "DLI (Daily Light Integral)", "defn": "DLI (daily light integral) is the total number of PAR photons that a surface receives in one day, in moles for each square meter (mol/m2/day). DLI = PPFD x seconds of light in each day / 1,000,000. It is the dose that has the largest effect on the yield.", "tags": ["reference"]},
    {"term": "Spectrum", "defn": "The spectrum is the mixture of the colors of light (wavelengths) that a fixture gives. Blue (400 to 500 nm) gives compact growth. Red (600 to 700 nm) causes flowering and is the range with the highest efficiency for photosynthesis.", "tags": ["reference"]},
    {"term": "Kelvin (K) / color temperature", "defn": "The color temperature, in kelvin (K), is a value that shows the mixture of colors of a white LED. A higher value (4000 to 6500 K) gives more blue and is for the vegetative stage. A lower value (3000 to 3500 K) gives more red and is for the flowering stage.", "tags": ["reference"]},
    {"term": "Efficacy (umol/J)", "defn": "Efficacy is the number of PAR photons that a fixture makes for each joule of electricity (umol/J). It is the primary number for the efficiency when you compare lights. Good LEDs have approximately 2.7 to 3.0 umol/J, HPS lights have approximately 1.7 to 1.9, and CMH lights have approximately 1.3 to 1.9.", "tags": ["reference"]},
    {"term": "PPF (Photosynthetic Photon Flux)", "defn": "PPF (photosynthetic photon flux) is the total number of PAR photons that a fixture gives in each second (umol/s). It does not show where the photons go. To get the efficacy, divide the PPF by the power of the fixture in watts.", "tags": ["reference"]},
    {"term": "Phytochrome", "defn": "Phytochrome is a pigment in a plant that senses red light and far-red light. It changes between the active condition (Pfr, 'it is day') and the condition that is not active (Pr). It measures the length of the continuous period of darkness and starts the flowering signal.", "tags": ["reference"]},
    {"term": "Florigen", "defn": "Florigen is a protein that moves in the plant and is the flowering signal. The leaves make it when the nights are sufficiently long. It moves to the growth tips, and it causes them to make buds and not leaves.", "tags": ["reference"]},
    {"term": "Far-red", "defn": "Far-red is light of approximately 700 to 750 nm, immediately after the PAR range. Phytochrome senses far-red light, and far-red light can make the plant sense the start of the night more quickly. Far-red light causes some stretch of the stem, and high doses of it can decrease the density of the buds.", "tags": ["reference"]},
    {"term": "UV-B", "defn": "UV-B is ultraviolet light of approximately 280 to 315 nm. Some growers add it in the last stage of flowering to try to increase the trichomes and the potency. The data do not agree, and UV-B causes risks to the eyes, the skin and the plants (stress).", "tags": ["reference"]},
    {"term": "Inverse-square law", "defn": "The inverse-square law is a relation in which the light intensity decreases with the square of the distance. When the gap between the fixture and the canopy becomes two times larger, the PPFD decreases by approximately 75%. Thus the hanging height is a control of the intensity with large steps.", "tags": ["reference"]},
    {"term": "PPFD map / PAR map", "defn": "A PPFD map (PAR map) is a grid from the manufacturer that shows the PPFD across the area below the fixture for specified hanging heights. Use the grid as a start point. Then measure the PPFD with your meter at the canopy height, to make sure that the grid is correct.", "tags": ["reference"]},
    {"term": "Uniformity (min-to-average ratio)", "defn": "Uniformity shows how equally the light goes to all the parts of the canopy. You read the PPFD at nine grid points and divide the lowest value by the average value. A value of more than 0.75 is sufficiently equal.", "tags": ["reference"]},
    {"term": "Light saturation", "defn": "Light saturation is the condition in which a plant cannot use more light, because CO2, water, nutrients, temperature or genetics is the limiting factor. Then more light intensity adds cost and stress, and it does not add yield.", "tags": ["reference"]},
    {"term": "Light stress / bleaching", "defn": "Light stress (bleaching) is damage from too much light intensity. You see the damage as white or yellow bud tips directly below the fixture, leaves with edges that bend up, and less color. The correction is to decrease the intensity of the light or to lift the fixture, and not to apply more feed.", "tags": ["reference"]},
    {"term": "Nutrient (essential element)", "defn": "A nutrient (essential element) is one of the chemical elements that a plant must absorb for correct growth. The primary nutrients for cannabis are N, P, K, Ca, Mg and S. The plant must also absorb trace micronutrients such as iron and zinc.", "tags": ["reference"]},
    {"term": "Macronutrient", "defn": "A macronutrient is an element that a plant must absorb in large quantities. The macronutrients are nitrogen (N), phosphorus (P), potassium (K), calcium (Ca), magnesium (Mg) and sulfur (S).", "tags": ["reference"]},
    {"term": "Micronutrient", "defn": "A micronutrient is an element that a plant must absorb only in very small quantities. The micronutrients are iron (Fe), manganese (Mn), zinc (Zn), copper (Cu), boron (B) and molybdenum (Mo).", "tags": ["reference"]},
    {"term": "Mobile nutrient", "defn": "A mobile nutrient is a nutrient that the plant can move from the old leaves to the new growth when the supply is not sufficient. The mobile nutrients are N, P, K and Mg. As a result, the deficiency of a mobile nutrient shows first on the old leaves at the bottom of the plant.", "tags": ["reference"]},
    {"term": "Immobile nutrient", "defn": "An immobile nutrient is a nutrient that stays where the plant first puts it, and the plant cannot move it to a different position. The immobile nutrients are Ca, S, Fe, Mn, Zn, B, Cu and Mo. As a result, the deficiency shows first on the new growth at the top of the plant.", "tags": ["reference"]},
    {"term": "Chlorosis", "defn": "Chlorosis is the condition in which leaf tissue becomes yellow because the quantity of green chlorophyll decreases.", "tags": ["reference"]},
    {"term": "Interveinal chlorosis", "defn": "Interveinal chlorosis is chlorosis between the veins of the leaf. The veins stay green. You see this condition with problems of magnesium, iron and manganese.", "tags": ["reference"]},
    {"term": "Necrosis", "defn": "Necrosis is the condition in which leaf tissue dies. The tissue becomes brown and dry, and it breaks easily. It occurs frequently at the tips or the edges of the leaves.", "tags": ["reference"]},
    {"term": "Deficiency", "defn": "A deficiency is the condition in which the plant does not get a sufficient quantity of a nutrient. The plant has less color, becomes yellow, and its growth is slow.", "tags": ["reference"]},
    {"term": "Toxicity", "defn": "Toxicity is the condition in which the plant has too much of a nutrient, or too much salt in total. The leaves are usually dark green and glossy, with tips that bend down, and the tips have tipburn. The signs are opposite to the signs of a deficiency.", "tags": ["reference"]},
    {"term": "pH lockout", "defn": "A pH lockout is a condition in which a nutrient is in the root zone, but the plant cannot absorb it. It occurs because the pH of the root zone is not in the range in which that nutrient stays in solution.", "tags": ["reference"]},
    {"term": "PPM (parts per million)", "defn": "PPM (parts per million) is a unit for the concentration of nutrients in water, and the PPM value changes with the EC value. Different scales change the EC value to a PPM value. Thus the EC value is the same for all meters, and the PPM value is not.", "tags": ["reference"]},
    {"term": "Nutrient burn", "defn": "Nutrient burn is the condition in which the tips and the edges of the leaves become brown. It occurs when you apply a solution that is too strong (too much salt). It is one type of toxicity.", "tags": ["reference"]},
    {"term": "The claw", "defn": "The claw is the condition in which the tips of the leaves bend down. It is the usual sign of toxicity of nitrogen (too much feed).", "tags": ["reference"]},
    {"term": "Nutrient antagonism", "defn": "Nutrient antagonism is the condition in which too much of one element stops the uptake of a different element. For example, too much potassium decreases the uptake of calcium and magnesium.", "tags": ["reference"]},
    {"term": "Flush", "defn": "A flush is the procedure in which you apply water that flows through the substrate and removes the salts that collect. The water has the correct pH, and it has no fertilizer or a small quantity of fertilizer. Thus the root zone is in its initial condition again.", "tags": ["reference"]},
    {"term": "Buffer (buffering)", "defn": "Buffering is the resistance of a substrate to a change of pH. Soil has high buffering, and coco and hydroponics have almost no buffering. Thus you must control the pH of coco and hydroponics with more precision.", "tags": ["reference"]},
    {"term": "Root zone", "defn": "The root zone is the wet substrate directly around the roots. The uptake of nutrients and water occurs there.", "tags": ["reference"]},
    {"term": "Nutrient lockout", "defn": "Nutrient lockout is the condition in which nutrients are in the substrate, but the roots cannot absorb them because of chemical bonds. It usually occurs because the pH changes to a value that is not in the correct range. The signs are the same as the signs of a deficiency.", "tags": ["reference"]},
    {"term": "Substrate (medium)", "defn": "A substrate (medium) is the material in which the roots extend. It can be coco coir, rockwool, water (hydroponics) or soil. The buffering of the pH in the root zone is different for each type of substrate.", "tags": ["reference"]},
    {"term": "Hydroponics", "defn": "Hydroponics is a method in which the roots are in a nutrient solution, or in an inert medium that receives it, and not in soil. The pH of the solution must have a value that is acid but near neutral. You must control the pH with precision.", "tags": ["reference"]},
    {"term": "Buffering capacity", "defn": "Buffering capacity is the resistance of a substrate or of water to a change of pH. High buffering gives a small change of pH (soil). Low buffering gives a fast change of pH (coco, hydroponics).", "tags": ["reference"]},
    {"term": "Alkalinity", "defn": "Alkalinity is the capacity of water to neutralize acid. The capacity comes mostly from bicarbonates, and you give the value as ppm of calcium carbonate (CaCO3). Alkalinity is not the same as a high pH reading.", "tags": ["reference"]},
    {"term": "Bicarbonate (HCO3-)", "defn": "Bicarbonate is the primary compound in the water that causes alkalinity. It neutralizes the acid that you add, and thus the pH increases again.", "tags": ["reference"]},
    {"term": "pH Down / pH Up", "defn": "The pH Down solution is an acid, usually phosphoric acid. The pH Up solution is alkaline, usually potassium hydroxide. You use them to adjust the pH.", "tags": ["reference"]},
    {"term": "Two-point calibration", "defn": "A two-point calibration is the calibration of a pH pen with two known buffers, usually pH 7.0 and then pH 4.0. Thus the pH pen gives accurate readings across the range that you use.", "tags": ["reference"]},
    {"term": "Buffer solution", "defn": "A buffer solution is a liquid with a pH that you know accurately, for example 4.0 or 7.0. You use it to calibrate a pH pen.", "tags": ["reference"]},
    {"term": "KCl storage solution", "defn": "KCl storage solution is a solution of potassium chloride that keeps the tip of a pH probe wet. If you keep the probe dry or in water without KCl, the probe has permanent damage.", "tags": ["reference"]},
    {"term": "Probe drift", "defn": "Probe drift is the condition in which the accuracy of a pH probe decreases gradually with time. Replace the probe when the drift is more than approximately 0.2 pH between calibrations.", "tags": ["reference"]},
    {"term": "Flip (12/12)", "defn": "The flip is the change of the grow light timer to 12 hours on and 12 hours off. The change causes flowering in photoperiod plants.", "tags": ["reference"]},
    {"term": "Stretch", "defn": "Stretch is the fast vertical growth in the first 2 to 3 weeks of flowering. In this time, the plant can become almost two times higher. Then the plant makes buds.", "tags": ["reference"]},
    {"term": "Pistil", "defn": "A pistil is a thin hair that extends from a bud site. It is white when it is new, and it becomes orange or brown during ripening. It is an approximate sign of the time to harvest, and it is not accurate.", "tags": ["reference"]},
    {"term": "Trichome", "defn": "A trichome is a very small gland of resin on the buds. It contains most of the THC and the aroma. The color of the trichome (clear, milky white or amber) is the primary signal for the harvest.", "tags": ["reference"]},
    {"term": "Calyx", "defn": "A calyx is one small part of the flower, in the shape of a drop. Many calyxes together make a bud.", "tags": ["reference"]},
    {"term": "Cola", "defn": "A cola is a large group of buds with a high density on a primary stem. The cola is usually the flower at the top of the plant, and it has the best growth.", "tags": ["reference"]},
    {"term": "Bud set", "defn": "Bud set is the time, approximately in weeks 3 to 4, when the pistils make small buds with a clear shape that become larger. Before this time, the pistils are at different positions.", "tags": ["reference"]},
    {"term": "Bulking", "defn": "Bulking is the middle phase of flowering (approximately weeks 5 to 7). In this phase, the mass of the buds increases at the highest rate.", "tags": ["reference"]},
    {"term": "Ripening", "defn": "Ripening is the last phase before harvest. In this phase, the pistils darken, the trichomes come to maturity, and the plant moves the nutrients that it keeps into the buds.", "tags": ["reference"]},
    {"term": "Defoliation", "defn": "Defoliation is the removal of selected leaves. Thus more light and more air go into the canopy.", "tags": ["reference"]},
    {"term": "Hermaphroditism (hermie)", "defn": "Hermaphroditism is the condition in which a female plant in stress makes male parts. The pollen from the male parts pollinates the plant, and the buds then have seeds. A frequent cause is a light leak in the period of darkness.", "tags": ["reference"]},
    {"term": "Bud rot (botrytis)", "defn": "Bud rot (botrytis) is a gray mold that causes rot in buds with a high density, when the humidity is high. It is a primary risk in the last stage of flowering. Because of this risk, growers decrease the humidity.", "tags": ["reference"]},
    {"term": "IPM (Integrated Pest Management)", "defn": "IPM (integrated pest management) is a method with layers: you prevent pests, monitor the crop, use biological control and apply treatments for specified pests. IPM does not use a spray at regular intervals. This paper identifies the pests, and the IPM SOP is the procedure for decisions.", "tags": ["reference"]},
    {"term": "Biocontrol / beneficial", "defn": "A biocontrol, or beneficial organism, is an organism that you release to decrease the quantity of a pest. It can be a predator mite, a parasitoid wasp, or a microbe such as a fungus or a bacterium.", "tags": ["reference"]},
    {"term": "Preventative vs curative", "defn": "A preventative agent is an agent that you put in the crop before pests come. It stays in the crop on an alternative food. A curative agent is an agent that you release to decrease an outbreak that is in progress and that becomes larger.", "tags": ["reference"]},
    {"term": "Life cycle / generation time", "defn": "The life cycle (generation time) is the time from the egg stage to the egg-laying adult. In warm dry rooms, this time is less than one week for spider mites. As a result, infestations increase very quickly.", "tags": ["reference"]},
    {"term": "Stippling", "defn": "Stippling is a group of small points with less color on the leaves. It occurs when pests make holes in the cells one by one and absorb the sap. It is a usual sign of spider mites and thrips.", "tags": ["reference"]},
    {"term": "Honeydew", "defn": "Honeydew is tacky waste with sugar from aphids and whitefly. It is on the leaves, and black sooty mold occurs on it.", "tags": ["reference"]},
    {"term": "Loupe / scope", "defn": "A loupe or scope is a magnifier for inspection. A hand loupe of 30x finds spider mites. You must use a magnification of 60 to 100x to find russet mites and broad mites.", "tags": ["reference"]},
    {"term": "Parasitoid wasp", "defn": "A parasitoid wasp is a very small wasp that is not dangerous to persons, for example Aphidius or Encarsia. The wasp puts eggs in a host pest, and the larva becomes larger and kills the host pest. These wasps are important for aphids and whitefly.", "tags": ["reference"]},
    {"term": "Bti / Btk", "defn": "Bti and Btk are types of the soil bacterium Bacillus thuringiensis. Bti (israelensis) kills the larvae of fungus gnats, and Btk (kurstaki) kills caterpillars. The two types kill the pest only when the pest eats them.", "tags": ["reference"]},
    {"term": "Entomopathogenic nematodes", "defn": "Entomopathogenic nematodes are very small worms, for example Steinernema feltiae. You apply them as a drench to the substrate. They are parasites of fungus gnat larvae, and they kill the larvae.", "tags": ["reference"]},
    {"term": "PPM / TDS", "defn": "PPM (parts per million), or TDS (total dissolved solids), is the total weight of all the materials in solution in water. PPM meters change the EC value to a PPM value with a 500 scale or a 700 scale. Thus two different meters can give different readings.", "tags": ["reference"]},
    {"term": "Carbonate / bicarbonate", "defn": "Carbonate and bicarbonate (CO3 and HCO3) are the compounds in solution that cause alkalinity. They neutralize the acid that you add. If the quantity is too large, they can cause lockout of calcium and magnesium.", "tags": ["reference"]},
    {"term": "Hardness", "defn": "Hardness is the quantity of calcium and magnesium in solution in water. You give it in ppm CaCO3 or in grains for each gallon (1 GPG is 17.1 mg/L). Soft water has less than approximately 1 GPG, and very hard water has more than approximately 10.5 GPG.", "tags": ["reference"]},
    {"term": "Chlorine", "defn": "Chlorine is a disinfectant that suppliers frequently add to tap water. It moves from the water into the air as a gas in approximately 24 hours if you keep the water in a container with aeration. Chlorine can cause damage to the tips of the roots and to beneficial microbes at low concentrations.", "tags": ["reference"]},
    {"term": "Chloramine", "defn": "Chloramine is a disinfectant of chlorine and ammonia that is more stable than chlorine. It does not go out of the water as a gas when you keep the water in a container. To remove it, you must use a catalytic carbon filter or reverse osmosis.", "tags": ["reference"]},
    {"term": "Reverse osmosis (RO)", "defn": "Reverse osmosis (RO) is filtration in which you push water through a semipermeable membrane. The membrane removes most of the minerals in solution, and the water has almost no PPM (usually 0 to 10 ppm TDS).", "tags": ["reference"]},
    {"term": "Build back", "defn": "Build back is the procedure in which you add minerals again to RO water or rainwater that has almost no minerals. The procedure is necessary because the plant must continue to get calcium, magnesium and some buffer. You usually add a CalMag supplement and the primary nutrients.", "tags": ["reference"]},
    {"term": "CalMag", "defn": "CalMag is a supplement of calcium and magnesium, frequently with iron. You add it to water that has a small quantity of minerals, such as RO water, rainwater or very soft tap water. It prevents a deficiency of calcium and magnesium.", "tags": ["reference"]},
    {"term": "Dissolved oxygen (DO)", "defn": "Dissolved oxygen (DO) is the quantity of oxygen in solution in water, and the roots must have it. DO decreases when the temperature of the water increases, from approximately 5 to 6 ppm at 20 °C to 3 to 4 ppm at 26 °C. A low DO increases the risk of root disease.", "tags": ["reference"]},
    {"term": "Sodium (Na)", "defn": "Sodium (Na) is a salt that is not a nutrient. Well water or coastal water can have a high quantity of sodium. A high quantity of sodium decreases the uptake of nutrients, and thus it is important to select RO.", "tags": ["reference"]},
    {"term": "Substrate (growing medium)", "defn": "A substrate (growing medium) is the material in which the roots of a plant extend. It holds the plant in position, and it contains water, air and nutrients in solution.", "tags": ["reference"]},
    {"term": "Water-holding capacity", "defn": "Water-holding capacity is the part of the pore space of a substrate that keeps water after the substrate drains. You give it as a percentage by volume.", "tags": ["reference"]},
    {"term": "Air-filled porosity", "defn": "Air-filled porosity is the part of the pore space of a substrate that holds air immediately after the substrate drains. When the air-filled porosity increases, the water-holding capacity decreases.", "tags": ["reference"]},
    {"term": "Total porosity", "defn": "Total porosity is the fraction of a substrate that is open pore space (air plus water) and not solid material.", "tags": ["reference"]},
    {"term": "CEC (cation exchange capacity)", "defn": "CEC (cation exchange capacity) shows how strongly a substrate holds cations, which are nutrient ions with a positive electric charge (in meq/100g). A high CEC gives more buffering of errors in the feed.", "tags": ["reference"]},
    {"term": "Buffering", "defn": "Buffering is the capacity of a substrate to absorb errors in the pH or in the strength of the nutrients. Thus the environment of the roots is more stable.", "tags": ["reference"]},
    {"term": "Rockwool (stonewool)", "defn": "Rockwool (stone wool) is an inert medium of fiber from molten rock. It drains freely, it holds a large quantity of water, and it has almost no buffering. It is alkaline until you soak it.", "tags": ["reference"]},
    {"term": "Peat", "defn": "Peat is bog moss that is not fully decomposed. It has a high air-filled porosity, it is acid, and it has a high CEC. Peat is the primary component of most soil mixtures in bags.", "tags": ["reference"]},
    {"term": "Living soil (ROLS)", "defn": "Living soil (ROLS) is an organic soil bed with a large quantity of microbes (recycled organic living soil). The soil has buffering for the pH and supplies nutrients to the plants through its biology. You apply only water, and you can use the soil again and again.", "tags": ["reference"]},
    {"term": "DWC (deep water culture)", "defn": "DWC (deep water culture) is hydroponics in which the roots hang in nutrient water with oxygen, and there is no solid medium. An air pump supplies the oxygen.", "tags": ["reference"]},
    {"term": "Pre-buffering", "defn": "Pre-buffering is the procedure in which you soak coco that you cleaned with water in a solution of calcium and magnesium. Thus the exchange sites of the coco do not remove Ca and Mg from your feed.", "tags": ["reference"]},
    {"term": "Cal-mag", "defn": "Cal-mag is a supplement of calcium and magnesium. It is necessary when you use coco, to prevent the deficiency that the CEC of the coco causes.", "tags": ["reference"]},
    {"term": "Inert medium", "defn": "An inert medium is a substrate, such as rockwool, that does not contain nutrients. Thus the plant gets only the nutrients that you apply in the feed.", "tags": ["reference"]},
    {"term": "Pythium", "defn": "Pythium is a water mold and a pathogen that causes root rot. It increases in number quickly in a reservoir where the water is warm (more than 23 °C) and the oxygen content is low.", "tags": ["reference"]},
]
